import sys

def main():
    data = sys.stdin.read().split()
    s, p = data[0], data[1]
    n, m = len(s), len(p)
    prev = [False] * (m + 1)
    prev[0] = True
    for j in range(2, m + 1):
        if p[j - 1] == '*':
            prev[j] = prev[j - 2]
    for i in range(1, n + 1):
        cur = [False] * (m + 1)
        ch = s[i - 1]
        for j in range(1, m + 1):
            pc = p[j - 1]
            if pc == '*':
                q = p[j - 2]
                cur[j] = cur[j - 2] or ((q == '.' or q == ch) and prev[j])
            else:
                cur[j] = (pc == '.' or pc == ch) and prev[j - 1]
        prev = cur
    print('true' if prev[m] else 'false')

main()

