def gen(rng):
    def rand_pat(k, alpha):
        out = []
        for _ in range(k):
            c = rng.choice(alpha + '.')
            out.append(c)
            if rng.random() < 0.4:
                out.append('*')
        return ''.join(out)
    def sample_from(p, alpha):
        out = []
        i = 0
        while i < len(p):
            c = p[i]
            star = i + 1 < len(p) and p[i + 1] == '*'
            ch = rng.choice(alpha) if c == '.' else c
            if star:
                out.append(ch * rng.randint(0, 3))
                i += 2
            else:
                out.append(ch)
                i += 1
        return ''.join(out)
    tests = [('a', 'a'), ('a', '.'), ('a', 'b'), ('aa', 'a'), ('aa', 'a*'), ('ab', '.*'), ('abc', '.*c'), ('abc', '.*d'),
             ('a', 'ab*'), ('b', 'a*b'), ('aaa', 'a*a'), ('aaa', 'ab*a*c*a'), ('ab', '.*c'), ('xy', 'x*y*z*.')]
    for _ in range(26):
        alpha = rng.choice(['a', 'ab', 'abc'])
        p = rand_pat(rng.randint(1, 6), alpha)
        if rng.random() < 0.6:
            s = sample_from(p, alpha)
            if not s:
                s = rng.choice(alpha)
            if rng.random() < 0.3:
                k = rng.randint(0, len(s) - 1)
                s = s[:k] + rng.choice(alpha) + s[k + 1:]
        else:
            s = ''.join(rng.choice(alpha) for _ in range(rng.randint(1, 8)))
        tests.append((s, p))
    tests.append(('a' * 1000, 'a*' * 400 + 'b'))
    tests.append(('a' * 1000, 'a*' * 499 + 'a'))
    tests.append(('a' * 999 + 'b', 'a*' * 400 + '.*b'))
    tests.append(('ab' * 500, '.*'))
    tests.append(('ab' * 500, '.*' + 'b*' * 200 + 'c'))
    s = ''.join(rng.choice('ab') for _ in range(1000))
    p = ''.join(('.' if rng.random() < 0.3 else c) for c in s)
    tests.append((s, p))
    s = ''.join(rng.choice('abc') for _ in range(320))
    p = ''
    for c in s:
        r = rng.random()
        if r < 0.2:
            p += '.'
        elif r < 0.5:
            p += c + '*'
        else:
            p += c
        if rng.random() < 0.1:
            p += 'z*'
    tests.append((s, p[:1000] if p[999:1000] != '*' else p[:999]))
    return [a + '\n' + b for a, b in tests]

